INSERT INTO _migration_308_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_clerical_b005_038' AND NOT (q.topic_id IS 'topic_was_clerical_b005_8' AND q.subject_id IS 'subj_wassce_clerical' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why is an itinerary prepared for business travel?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Remove or secure the hazard using an approved cable route","B. To coordinate times, locations, transport, accommodation and contacts","C. To prevent schedule conflicts and support punctual, prepared attendance","D. To state the business and intended order of discussion"]' AND q.correct_answer IS 'B' AND q.explanation IS 'A complete itinerary reduces missed connections and gives the traveller and office a shared operational plan. Therefore the correct answer is B: To coordinate times, locations, transport, accommodation and contacts.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_clerical_b005_8' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_clerical_b005_038' AND NOT (r.batch_id IS 'wassce-foundation-beta-005' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Clerical Office Duties practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2023/03/Business21.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_308_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_clerical_b005_039' AND NOT (q.topic_id IS 'topic_was_clerical_b005_8' AND q.subject_id IS 'subj_wassce_clerical' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the safest response to a trailing electrical cable across a walkway?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. To prevent schedule conflicts and support punctual, prepared attendance","B. To state the business and intended order of discussion","C. Remove or secure the hazard using an approved cable route","D. Key decisions, actions, responsible persons and relevant discussion outcomes"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Uncontrolled cables cause trips and damage; the route should be corrected rather than relying only on people to notice it. Therefore the correct answer is C: Remove or secure the hazard using an approved cable route.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_clerical_b005_8' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_clerical_b005_039' AND NOT (r.batch_id IS 'wassce-foundation-beta-005' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Clerical Office Duties practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2023/03/Business21.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
